// Prüft die Länder-Sperre im Browser: AT/CH zeigen den Hinweis und keine €-/ct-/EEG-Werte im Rechner,
// DE zeigt das Ergebnis. Aufruf: node sperre-check.mjs <basis> <ausgabeordner>
import { createRequire } from "node:module";
import { mkdirSync } from "node:fs";
const require = createRequire("C:/Users/SALEADMIN/claude-browser/package.json");
const { chromium } = require("playwright");

const [basis = "http://localhost:3100", out = "."] = process.argv.slice(2);
mkdirSync(out, { recursive: true });

const FAELLE = [
  ["/rechner/solarpark?regionId=at", "AT"],
  ["/rechner/solarpark?regionId=ch", "CH"],
  ["/rechner/solarpark", null],
  ["/rechner/pacht?regionId=at", "AT"],
  ["/rechner/pacht?regionId=ch", "CH"],
  ["/rechner/pacht", null],
  ["/rechner/agri-pv?regionId=at", "AT"],
  ["/rechner/agri-pv?regionId=ch", "CH"],
  ["/rechner/dachpacht?regionId=at", "AT"],
  ["/rechner/solarcarport?regionId=ch", "CH"],
  ["/rechner/bestandsanlage?regionId=at", "AT"],
  ["/rechner/pachtangebot-check?regionId=at", "AT"],
  ["/rechner/beteiligung?regionId=ch", "CH"],
  ["/rechner/netzanschluss?land=at", "AT"],
  ["/rechner/kommune?regionId=at", null],
  ["/rechner/energy-sharing", null],
];

// Muster, die bei gesperrtem Land im Rechner NICHT vorkommen dürfen
const VERBOTEN = [/€/, /ct\/kWh/, /\bEEG\b/, /GAP/, /Rp\./];

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
await ctx.addCookies([{ name: "cookieConsent", value: JSON.stringify({ notwendig: true }), url: basis }]);
const page = await ctx.newPage();
let fehlerGesamt = 0;
for (const [pfad, land] of FAELLE) {
  const konsole = [];
  const onC = (m) => m.type() === "error" && konsole.push(m.text());
  const onE = (e) => konsole.push(String(e));
  page.on("console", onC);
  page.on("pageerror", onE);
  try {
    const r = await page.goto(basis + pfad, { waitUntil: "load", timeout: 180000 });
    await page.waitForTimeout(2500);
    const rechner = page.locator("[data-rechner]").first();
    await rechner.scrollIntoViewIfNeeded().catch(() => {});
    const text = (await rechner.innerText().catch(() => "")) || "";
    const sperre = await page.locator("[data-laender-sperre]").count();
    const name = pfad.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "");
    await rechner.screenshot({ path: `${out}/${name}.png` }).catch(() => {});
    let ok = r && r.status() === 200 && konsole.length === 0;
    const notizen = [];
    if (land) {
      if (sperre !== 1) { ok = false; notizen.push("kein Sperrhinweis"); }
      for (const v of VERBOTEN) if (v.test(text)) { ok = false; notizen.push(`enthält ${v}`); }
    } else if (sperre !== 0) { ok = false; notizen.push("Sperrhinweis bei DE"); }
    if (!ok) fehlerGesamt++;
    console.log(`${ok ? "OK  " : "!!  "} ${pfad} status=${r?.status()} sperre=${sperre} ${notizen.join(", ")} konsole=${konsole.length}`);
    konsole.slice(0, 2).forEach((k) => console.log("     ! " + k.slice(0, 200)));
  } catch (e) {
    fehlerGesamt++;
    console.log(`!!   ${pfad} LADEFEHLER ${String(e).slice(0, 150)}`);
  }
  page.off("console", onC);
  page.off("pageerror", onE);
}
await browser.close();
console.log(fehlerGesamt ? `${fehlerGesamt} Fehler` : "alle Fälle bestanden");
process.exit(fehlerGesamt ? 1 : 0);

